    // Implementation note: Declarations must precede use in this namespace or enclosing ones.
    namespace Inner {
        int var;  // Declare before use
        void func() {  // Compiler checks for 'var' in Inner, then Outer, then global scope
            std::cout << var;  // 'var' must be declared before this line in the namespace
        }
    }
}
